  opt_select:          { en: "Select",            ar: "\u0627\u062e\u062a\u0631",             id: "Pilih" },
  opt_bachelors:       { en: "Bachelor\u2019s",      ar: "\u0628\u0643\u0627\u0644\u0648\u0631\u064a\u0648\u0633",          id: "Sarjana" },
  opt_masters:         { en: "Master\u2019s",        ar: "\u0645\u0627\u062c\u0633\u062a\u064a\u0631",           id: "Magister" },
  opt_phd:             { en: "PhD",               ar: "\u062f\u0643\u062a\u0648\u0631\u0627\u0647",           id: "Doktoral" },
  opt_other:           { en: "Other",             ar: "\u0623\u062e\u0631\u0649",             id: "Lainnya" },
  opt_native:          { en: "Native",            ar: "\u0644\u063a\u0629 \u0623\u0645",           id: "Penutur asli" },
  opt_undergrad:       { en: "Undergraduate",     ar: "\u0628\u0643\u0627\u0644\u0648\u0631\u064a\u0648\u0633",          id: "Sarjana" },
  opt_masters_student: { en: "Master\u2019s student", ar: "\u0637\u0627\u0644\u0628 \u0645\u0627\u062c\u0633\u062a\u064a\u0631",      id: "Mahasiswa magister" },
  opt_phd_student:     { en: "PhD student",       ar: "\u0637\u0627\u0644\u0628 \u062f\u0643\u062a\u0648\u0631\u0627\u0647",      id: "Mahasiswa doktoral" },
  opt_3m:              { en: "3 months",          ar: "3 \u0623\u0634\u0647\u0631",           id: "3 bulan" },
  opt_6m:              { en: "6 months",          ar: "6 \u0623\u0634\u0647\u0631",           id: "6 bulan" },
  opt_1y:              { en: "1 year",            ar: "\u0633\u0646\u0629 \u0648\u0627\u062d\u062f\u0629",         id: "1 tahun" },
  opt_2y:              { en: "2 years",           ar: "\u0633\u0646\u062a\u0627\u0646",            id: "2 tahun" },
  opt_full:            { en: "Full program",      ar: "\u0627\u0644\u0628\u0631\u0646\u0627\u0645\u062c \u0643\u0627\u0645\u0644\u0627\u064b",     id: "Program penuh" },
  opt_lab_website:     { en: "Lab website",       ar: "\u0645\u0648\u0642\u0639 \u0627\u0644\u0645\u062e\u062a\u0628\u0631",        id: "Situs web lab" },
  opt_faculty:         { en: "Faculty referral",  ar: "\u062a\u0631\u0634\u064a\u062d \u0623\u0643\u0627\u062f\u064a\u0645\u064a",       id: "Rujukan dosen" },
  opt_conference:      { en: "Conference",        ar: "\u0645\u0624\u062a\u0645\u0631",             id: "Konferensi" },
  opt_twitter:         { en: "Twitter/X",         ar: "Twitter/X",         id: "Twitter/X" },
  opt_linkedin:        { en: "LinkedIn",          ar: "LinkedIn",          id: "LinkedIn" },
  opt_jobboard:        { en: "Job board",         ar: "\u0645\u0646\u0635\u0629 \u062a\u0648\u0638\u064a\u0641",        id: "Papan lowongan kerja" },

  /* ── Validation errors ── */
  err_required:        { en: "Required",                          ar: "\u0645\u0637\u0644\u0648\u0628",                       id: "Wajib diisi" },
  err_invalid_email:   { en: "Invalid email",                     ar: "\u0628\u0631\u064a\u062f \u0625\u0644\u0643\u062a\u0631\u0648\u0646\u064a \u063a\u064a\u0631 \u0635\u0627\u0644\u062d",      id: "Email tidak valid" },
  err_invalid_phone:   { en: "Invalid phone",                     ar: "\u0631\u0642\u0645 \u0647\u0627\u062a\u0641 \u063a\u064a\u0631 \u0635\u0627\u0644\u062d",         id: "Nomor telepon tidak valid" },
  err_score_required:  { en: "Score required",                    ar: "\u0627\u0644\u062f\u0631\u062c\u0629 \u0645\u0637\u0644\u0648\u0628\u0629",               id: "Skor wajib diisi" },
  err_cv_required:     { en: "CV required",                       ar: "\u0627\u0644\u0633\u064a\u0631\u0629 \u0627\u0644\u0630\u0627\u062a\u064a\u0629 \u0645\u0637\u0644\u0648\u0628\u0629",        id: "CV wajib diunggah" },
  err_pitch_required:  { en: "Pitch deck required",               ar: "\u0627\u0644\u0639\u0631\u0636 \u0627\u0644\u062a\u0642\u062f\u064a\u0645\u064a \u0645\u0637\u0644\u0648\u0628",        id: "Pitch deck wajib diunggah" },
  err_select_one:      { en: "Select at least one",               ar: "\u0627\u062e\u062a\u0631 \u0648\u0627\u062d\u062f\u064b\u0627 \u0639\u0644\u0649 \u0627\u0644\u0623\u0642\u0644",         id: "Pilih setidaknya satu" },
  err_specify:         { en: "Please specify",                    ar: "\u064a\u0631\u062c\u0649 \u0627\u0644\u062a\u062d\u062f\u064a\u062f",               id: "Harap sebutkan" },
  err_file_size:       { en: "File exceeds size limit",           ar: "\u0627\u0644\u0645\u0644\u0641 \u064a\u062a\u062c\u0627\u0648\u0632 \u0627\u0644\u062d\u062f \u0627\u0644\u0645\u0633\u0645\u0648\u062d",      id: "Ukuran file melebihi batas" },
  err_file_type:       { en: "Invalid file type",                 ar: "\u0646\u0648\u0639 \u0627\u0644\u0645\u0644\u0641 \u063a\u064a\u0631 \u0635\u0627\u0644\u062d",          id: "Jenis file tidak valid" },
  err_select_position: { en: "Select a position",                 ar: "\u0627\u062e\u062a\u0631 \u0648\u0638\u064a\u0641\u0629",                id: "Pilih posisi" },
  err_degree_phd:      { en: "PhD required for this position",    ar: "\u0647\u0630\u0647 \u0627\u0644\u0648\u0638\u064a\u0641\u0629 \u062a\u062a\u0637\u0644\u0628 \u062f\u0631\u062c\u0629 \u0627\u0644\u062f\u0643\u062a\u0648\u0631\u0627\u0647", id: "Posisi ini memerlukan gelar PhD" },

