  ph_affil_phd:   { en: "e.g. Research Assistant, MIT",      ar: "\u0645\u062b\u0627\u0644: \u0645\u0633\u0627\u0639\u062f \u0628\u0627\u062d\u062b\u060c MIT",            id: "mis. Asisten Peneliti, MIT" },
